CREATE TABLE laboratory_samples(id uuid PRIMARY KEY,order_id uuid UNIQUE NOT NULL REFERENCES laboratory_orders(id),barcode varchar(64) UNIQUE NOT NULL,collected_by uuid NOT NULL,collected_at timestamptz NOT NULL DEFAULT now(),status varchar(30) NOT NULL DEFAULT 'COLLECTED');CREATE TABLE laboratory_history(id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES laboratory_orders(id),previous_status text NOT NULL,next_status text NOT NULL,actor_id uuid NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now());
